using Microsoft.EntityFrameworkCore;
using System.ComponentModel.DataAnnotations;
namespace Moz;
public class Tenant { public Guid Id {get;set;}=Guid.NewGuid(); public string Name {get;set;}=""; public bool Active {get;set;}=true; public string Plan {get;set;}=""; public int TripLimit {get;set;}=0; }
