public class Trip { public Guid Id {get;set;}=Guid.NewGuid(); public Guid TenantId {get;set;} public Guid ClientId {get;set;} public string Code {get;set;}=""; public string DriverCpf {get;set;}=""; public Guid? DriverId {get;set;} public string DriverName {get;set;}=""; public string Carrier {get;set;}=""; public string Tractor {get;set;}=""; public string Trailer {get;set;}=""; public string Container {get;set;}=""; public string Status {get;set;}="Programada"; public DateTimeOffset Scheduled {get;set;} public DateTimeOffset Created {get;set;}=DateTimeOffset.UtcNow; public DateTimeOffset? Started {get;set;} public DateTimeOffset? TrackingSince {get;set;} public DateTimeOffset? Finished {get;set;} public DateTimeOffset? LastFix {get;set;} public double? LastLat {get;set;} public double? LastLon {get;set;} public double DistanceKm {get;set;} public double MaxSpeed {get;set;} public double MovingSeconds {get;set;} public double IdleSeconds {get;set;} public double SpeedLimit {get;set;}=80; public double MaxAccuracy {get;set;}=50; public int StopSeconds {get;set;}=180; public int GapSeconds {get;set;}=120; public int CurrentStage {get;set;} public bool GapAlerted {get;set;} public DateTimeOffset? StopSince {get;set;} public bool StopAlerted {get;set;} public double? StopLat {get;set;} public double? StopLon {get;set;} [Timestamp] public byte[] Version {get;set;}=Array.Empty<byte>(); }
public class Stage { public Guid Id {get;set;}=Guid.NewGuid(); public Guid TripId {get;set;} public int Order {get;set;} public string Label {get;set;}=""; public string Kind {get;set;}=""; public string Address {get;set;}=""; public double Lat {get;set;} public double Lon {get;set;} public double Radius {get;set;} public string? Polygon {get;set;} public bool RequirePod {get;set;} public bool FinishOnPod {get;set;} public int SlaMinutes {get;set;} public DateTimeOffset? Arrived {get;set;} public DateTimeOffset? WorkStart {get;set;} public DateTimeOffset? WorkEnd {get;set;} public DateTimeOffset? Departed {get;set;} public int InsideCount {get;set;} public int OutsideCount {get;set;} public DateTimeOffset? FirstInside {get;set;} public DateTimeOffset? FirstOutside {get;set;} public bool SlaAlerted {get;set;} }
