public class MozDb(DbContextOptions<MozDb> options):DbContext(options) {
 public DbSet<Tenant> Tenants=>Set<Tenant>(); public DbSet<User> Users=>Set<User>(); public DbSet<Client> Clients=>Set<Client>(); public DbSet<OperatorDriver> OperatorDrivers=>Set<OperatorDriver>(); public DbSet<Registry> Registry=>Set<Registry>(); public DbSet<Place> Places=>Set<Place>(); public DbSet<Trip> Trips=>Set<Trip>(); public DbSet<Stage> Stages=>Set<Stage>(); public DbSet<Fix> Fixes=>Set<Fix>(); public DbSet<EventLog> Events=>Set<EventLog>(); public DbSet<TripPlan> Plans=>Set<TripPlan>(); public DbSet<PushDevice> PushDevices=>Set<PushDevice>(); public DbSet<ReadNotice> Reads=>Set<ReadNotice>(); public DbSet<Pod> Pods=>Set<Pod>(); public DbSet<Audit> Audits=>Set<Audit>();
 protected override void OnModelCreating(ModelBuilder m) {
 m.Entity<User>().Property(x=>x.Login).HasMaxLength(256); m.Entity<User>().HasIndex(x=>x.Login).IsUnique();
 m.Entity<User>().Property(x=>x.Cpf).HasMaxLength(11); m.Entity<User>().HasIndex(x=>x.Cpf).IsUnique().HasFilter("[Cpf] IS NOT NULL");
 m.Entity<Client>().Property(x=>x.Cnpj).HasMaxLength(14);m.Entity<Client>().HasIndex(x=>new{x.TenantId,x.Cnpj}).IsUnique().HasFilter("[Cnpj] IS NOT NULL");
 m.Entity<OperatorDriver>().HasKey(x=>new{x.TenantId,x.Cpf});m.Entity<OperatorDriver>().Property(x=>x.Cpf).HasMaxLength(11);m.Entity<OperatorDriver>().Property(x=>x.Name).HasMaxLength(160);
 m.Entity<Trip>().Property(x=>x.DriverCpf).HasMaxLength(11); m.Entity<Trip>().HasIndex(x=>new{x.TenantId,x.Status}); m.Entity<Trip>().HasIndex(x=>x.DriverId); m.Entity<Trip>().HasIndex(x=>x.DriverCpf).IsUnique().HasFilter("[TrackingSince] IS NOT NULL AND [Finished] IS NULL"); m.Entity<Trip>().HasIndex(x=>x.ClientId);
 m.Entity<Trip>().Property(x=>x.Code).HasMaxLength(40); m.Entity<Trip>().HasIndex(x=>x.Code).IsUnique();
 m.Entity<Stage>().HasIndex(x=>new{x.TripId,x.Order}).IsUnique(); m.Entity<Fix>().HasIndex(x=>new{x.TripId,x.At}); m.Entity<EventLog>().HasIndex(x=>new{x.TripId,x.At}); m.Entity<ReadNotice>().HasKey(x=>new{x.UserId,x.EventId});
 m.Entity<TripPlan>().HasKey(x=>x.TripId);m.Entity<TripPlan>().HasOne<Trip>().WithOne().HasForeignKey<TripPlan>(x=>x.TripId).OnDelete(DeleteBehavior.Restrict);
 m.Entity<PushDevice>().Property(x=>x.EndpointHash).HasMaxLength(64);m.Entity<PushDevice>().HasIndex(x=>x.EndpointHash).IsUnique();m.Entity<PushDevice>().HasIndex(x=>x.NextAttempt);
 m.Entity<PushDevice>().HasOne<User>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);
 m.Entity<Pod>().HasIndex(x=>x.TripId);
 m.Entity<Trip>().HasOne<Tenant>().WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Restrict);
 m.Entity<Trip>().HasOne<Client>().WithMany().HasForeignKey(x=>x.ClientId).OnDelete(DeleteBehavior.Restrict);
 m.Entity<Stage>().HasOne<Trip>().WithMany().HasForeignKey(x=>x.TripId).OnDelete(DeleteBehavior.Restrict);
 m.Entity<Fix>().HasOne<Trip>().WithMany().HasForeignKey(x=>x.TripId).OnDelete(DeleteBehavior.Restrict);
 m.Entity<EventLog>().HasOne<Trip>().WithMany().HasForeignKey(x=>x.TripId).OnDelete(DeleteBehavior.Restrict);
 m.Entity<Pod>().HasOne<Trip>().WithMany().HasForeignKey(x=>x.TripId).OnDelete(DeleteBehavior.Restrict);
 }
}
